Excellent! J'ai toutes les informations. Voici un guide complet et structuré de next-intl.

## Documentation next-intl - Guide Complet

### 1. Configuration Initiale

#### **next.config.ts**
```typescript
import createNextIntlPlugin from 'next-intl/plugin';

const withNextIntl = createNextIntlPlugin();

const nextConfig = {
  // Autres configs...
};

export default withNextIntl(nextConfig);
```

---

### 2. Structure des Fichiers Recommandée

```
src/
├── app/
│   └── [locale]/
│       ├── layout.tsx
│       ├── page.tsx
│       └── (pages)/
│           └── about/
│               └── page.tsx
├── i18n/
│   ├── routing.ts
│   ├── request.ts
│   └── navigation.ts
└── middleware.ts (ou proxy.ts pour Next.js 16+)

messages/
├── en.json
├── fr.json
└── de.json
```

---

### 3. Configuration des Routes - `src/i18n/routing.ts`

```typescript
import { defineRouting } from 'next-intl/routing';

export const routing = defineRouting({
  // Locales supportées
  locales: ['en', 'fr', 'de'],
  // Locale par défaut
  defaultLocale: 'en',
  // (Optionnel) Pathnames personnalisés par langue
  pathnames: {
    '/': '/',
    '/about': {
      en: '/about',
      fr: '/a-propos',
      de: '/uber-uns'
    }
  }
});
```

---

### 4. Configuration Request - `src/i18n/request.ts`

```typescript
import { getRequestConfig } from 'next-intl/server';
import { hasLocale } from 'next-intl';
import { routing } from './routing';

export default getRequestConfig(async ({ requestLocale }) => {
  const requested = await requestLocale;

  // Valide la locale demandée
  const locale = hasLocale(routing.locales, requested)
    ? requested
    : routing.defaultLocale;

  return {
    locale,
    // Charge les messages pour la locale
    messages: (await import(`../../messages/${locale}.json`)).default,
    // (Optionnel) Timezone
    timeZone: 'Europe/Paris',
    // (Optionnel) Format personnalisé
    formats: {
      dateTime: {
        short: {
          year: 'numeric',
          month: 'short',
          day: 'numeric'
        }
      }
    }
  };
});
```

---

### 5. Middleware/Proxy - `src/middleware.ts` ou `src/proxy.ts` (Next.js 16+)

```typescript
import createMiddleware from 'next-intl/middleware';
import { routing } from './i18n/routing';

export default createMiddleware(routing);

export const config = {
  // Exclut les routes API, Next.js internals et fichiers statiques
  matcher: '/((?!api|trpc|_next|_vercel|.*\\..*).*)' 
};
```

**Ce que fait le middleware :**
- Détecte la locale par priorité : URL prefix → cookie → `accept-language` header → defaultLocale
- Applique les redirects/rewrites nécessaires
- Fournit alternate links pour les moteurs de recherche

---

### 6. Navigation Wrapper - `src/i18n/navigation.ts`

```typescript
import { createNavigation } from 'next-intl/navigation';
import { routing } from './routing';

export const { Link, redirect, usePathname, useRouter } = 
  createNavigation(routing);
```

**Utilisation :** Utilise ces wrappers au lieu des APIs Next.js natives pour respecter la configuration i18n.

---

### 7. Layout Principal avec generateStaticParams

```typescript
// app/[locale]/layout.tsx
import { setRequestLocale } from 'next-intl/server';
import { routing } from '@/i18n/routing';
import { notFound } from 'next/navigation';

export function generateStaticParams() {
  return routing.locales.map((locale) => ({ locale }));
}

export async function generateMetadata({ params }) {
  const { locale } = await params;
  const t = await getTranslations({ locale, namespace: 'Metadata' });

  return {
    title: t('title'),
    description: t('description'),
    alternates: {
      languages: Object.fromEntries(
        routing.locales.map((loc) => [
          loc,
          `/${loc}`
        ])
      )
    }
  };
}

export default async function LocaleLayout({
  children,
  params
}: {
  children: React.ReactNode;
  params: Promise<{ locale: string }>;
}) {
  const { locale } = await params;

  // Valide la locale
  if (!routing.locales.includes(locale as any)) {
    notFound();
  }

  // IMPORTANT : Doit être appelé avant les fonctions next-intl
  setRequestLocale(locale);

  return (
    <html lang={locale}>
      <body>
        {children}
      </body>
    </html>
  );
}
```

---

### 8. Utilisation dans Server Components

```typescript
// app/[locale]/page.tsx
import { getTranslations, setRequestLocale } from 'next-intl/server';

export default async function HomePage({ params }) {
  const { locale } = await params;
  setRequestLocale(locale);

  const t = await getTranslations('HomePage');
  const common = await getTranslations('Common');

  return (
    <main>
      <h1>{t('title')}</h1>
      <p>{t('description')}</p>
      <button>{common('submit')}</button>
    </main>
  );
}
```

**Points importants :**
- Utilise `await getTranslations()` - async function
- Doit appeler `setRequestLocale()` en premier
- La clé peut être un namespace (`'HomePage'`) ou un chemin complet

---

### 9. Utilisation dans Client Components

```typescript
'use client';

import { useTranslations } from 'next-intl';

export default function SubmitButton() {
  const t = useTranslations('Common');
  const tHome = useTranslations('HomePage');

  return (
    <button onClick={() => alert(t('success'))}>
      {t('submit')}
    </button>
  );
}
```

**Différences clés :**
- Hook `useTranslations()` (pas async)
- Peut être utilisé directement sans paramètres locaux
- La configuration vient automatiquement du `NextIntlClientProvider`

---

### 10. Layout avec NextIntlClientProvider

```typescript
// app/[locale]/layout.tsx
import { NextIntlClientProvider } from 'next-intl';
import { getMessages, setRequestLocale } from 'next-intl/server';

export default async function LocaleLayout({
  children,
  params
}: {
  children: React.ReactNode;
  params: Promise<{ locale: string }>;
}) {
  const { locale } = await params;
  setRequestLocale(locale);

  // Charge les messages côté serveur
  const messages = await getMessages();

  return (
    <NextIntlClientProvider messages={messages}>
      {children}
    </NextIntlClientProvider>
  );
}
```

---

### 11. Server Actions avec Traductions

```typescript
// app/[locale]/actions.ts
'use server';

import { getTranslations } from 'next-intl/server';

export async function submitForm(locale: string, data: FormData) {
  const t = await getTranslations({ locale, namespace: 'Forms' });

  // Validation avec messages localisés
  if (!data.get('email')) {
    return {
      error: t('email_required')
    };
  }

  return {
    success: t('submitted_successfully')
  };
}
```

---

### 12. Metadata Localisée

```typescript
// app/[locale]/about/page.tsx
import { getTranslations } from 'next-intl/server';

export async function generateMetadata({ params }) {
  const { locale } = await params;
  const t = await getTranslations({
    locale,
    namespace: 'Pages.About'
  });

  return {
    title: t('title'),
    description: t('description'),
    alternates: {
      canonical: `https://example.com/${locale}/about`
    }
  };
}

export default async function AboutPage() {
  const t = await getTranslations('Pages.About');
  return <h1>{t('title')}</h1>;
}
```

---

### 13. Fichier Messages (JSON)

```json
// messages/en.json
{
  "HomePage": {
    "title": "Welcome",
    "description": "Hello, world!"
  },
  "Common": {
    "submit": "Submit",
    "success": "Operation successful"
  },
  "Metadata": {
    "title": "My App",
    "description": "Welcome to my app"
  }
}
```

```json
// messages/fr.json
{
  "HomePage": {
    "title": "Bienvenue",
    "description": "Bonjour, le monde!"
  },
  "Common": {
    "submit": "Soumettre",
    "success": "Opération réussie"
  },
  "Metadata": {
    "title": "Mon App",
    "description": "Bienvenue sur mon app"
  }
}
```

---

### 14. Patterns de Rendu Statique

Pour **activer le rendu statique** avec les segments dynamiques `[locale]` :

```typescript
// app/[locale]/page.tsx
import { setRequestLocale } from 'next-intl/server';

export function generateStaticParams() {
  return [
    { locale: 'en' },
    { locale: 'fr' },
    { locale: 'de' }
  ];
}

export default async function Page({ params }) {
  const { locale } = await params;

  // Doit être appelé AVANT nextIntl
  setRequestLocale(locale);

  // Maintenant nextIntl functions fonctionnent en statique
}
```

---

### 15. Utilisation de Navigation

```typescript
'use client';

import { useRouter, usePathname } from '@/i18n/navigation';

export function LocaleSwitcher() {
  const router = useRouter();
  const pathname = usePathname();

  const switchLocale = (locale: string) => {
    // Navigue automatiquement avec la bonne URL
    router.push(pathname, { locale });
  };

  return (
    <select onChange={(e) => switchLocale(e.target.value)}>
      <option value="en">English</option>
      <option value="fr">Français</option>
    </select>
  );
}
```

